// Acquisition errors omit the preview-only assurance in errorDescription().
const acquisitionMessages = messages.filter(([ja]) => ja.includes('取得は始めていません。') && ja !== '取得は始めていません。')
  .map(([ja, en, zh]) => [ja.replace('取得は始めていません。', ''), en.replace(/Capture has not started\. ?/, ''), zh.replace('尚未开始获取。', '')]);
const entries = [...messages, ...acquisitionMessages].sort((a, b) => b[0].length - a[0].length);
const escape = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const pattern = new RegExp(entries.map(([key]) => escape(key)).join('|'), 'g');
const dictionary = new Map(entries.map(([key, en, zh]) => [key, { en, 'zh-CN': zh }]));
export function translateCopy(value, language = 'ja') {
  if (!['en', 'zh-CN'].includes(language)) return value;
  return value.replace(pattern, key => dictionary.get(key)[language]);
}
